import { createServer } from 'node:net';
import { unlinkSync } from 'node:fs';
export const PIPE = '/tmp/probehub.sock';
export const frame = (s: string) => Buffer.from(s + '\n');
export const listen = (path = PIPE) => {
  try { unlinkSync(path); } catch {}
  const server = createServer();
  server.listen(path);
  return server;
};
